//! DI registration for the rust-ef outbox store.
//!
//! The application owns the database registration: call rust-ef's
//! `add_dbcontext` (or `add_dbcontext_keyed`), add the outbox entity to the model
//! with [`register_outbox_model`](crate::register_outbox_model), then call
//! [`add_outbox_ef`](OutboxEfServiceCollectionExt::add_outbox_ef). The port, the
//! dispatcher and its options come from [`webx_outbox`]; this module only binds
//! the durable store. Migrations for the outbox table are generated by the
//! official rust-ef tooling: this crate never creates schema at runtime and
//! declares no routes.

use std::sync::Arc;

use rust_dix::{IServiceResolver, ScopeFactory, ServiceCollection};
use webx_host::server::HostBuilder;
use webx_outbox::{IOutbox, OutboxOptions, OutboxServiceCollectionExt};

use crate::ef_outbox::EfOutbox;

/// Register the rust-ef store and the framework outbox dispatcher.
pub trait OutboxEfServiceCollectionExt: Sized {
    /// Register `Arc<dyn IOutbox>` backed by rust-ef and, when
    /// `options.enabled`, the framework
    /// [`OutboxDispatcher`](webx_outbox::OutboxDispatcher).
    ///
    /// Requires a scoped rust-ef `DbContext` registered with `add_dbcontext`; the
    /// outbox resolves an owned context from a fresh DI scope per storage
    /// operation.
    fn add_outbox_ef(self, options: OutboxOptions) -> Self;
}

impl OutboxEfServiceCollectionExt for ServiceCollection {
    fn add_outbox_ef(self, options: OutboxOptions) -> Self {
        let max_attempts = options.max_attempts();
        self.add_outbox_with(
            move |resolver| {
                let services = resolve_scope_factory(resolver);
                Arc::new(EfOutbox::new(services, max_attempts)) as Arc<dyn IOutbox>
            },
            options,
        )
    }
}

/// Register the rust-ef outbox on a [`HostBuilder`] (`add_outbox_ef(...)`).
pub trait OutboxEfHostBuilderExt: Sized {
    /// Register the durable store and (when enabled) the dispatcher.
    fn add_outbox_ef(self, options: OutboxOptions) -> Self;
}

impl OutboxEfHostBuilderExt for HostBuilder {
    fn add_outbox_ef(self, options: OutboxOptions) -> Self {
        self.register(move |services| services.add_outbox_ef(options))
    }
}

/// The rust-dix built-in `ScopeFactory` is always resolvable from a built
/// provider; a failure here means the provider was built by hand without it.
fn resolve_scope_factory(resolver: &dyn IServiceResolver) -> Arc<dyn ScopeFactory> {
    rust_dix::IServiceResolverExt::resolve_arc::<dyn ScopeFactory>(resolver).expect(
        "rust-dix always provides the built-in Arc<dyn ScopeFactory>; \
         outbox registration requires a provider built by rust-dix",
    )
}
